/** Checks explicit targets and ensures validation errors do not echo the URI. */
function checkTargets() {
  const uri = 'mongodb+srv://demo:private-placeholder@cluster.example.org/akole_ccms_demo';
  assert.doesNotThrow(() => validateTarget('akole_ccms_demo', uri));
  for (const name of [undefined, 'admin', 'config', 'local', 'test', 'bad/name', 'other_demo']) {
    assert.throws(() => validateTarget(name, uri), SeedError);
  }
  for (const invalid of [undefined, 'not-a-uri', 'https://example.org/akole_ccms_demo', uri.replace('/akole_ccms_demo', '/')]) {
    assert.throws(() => validateTarget('akole_ccms_demo', invalid), SeedError);
  }
  assert.throws(() => validateTarget('another_db', uri), (error) =>
    error instanceof SeedError && !error.message.includes('private-placeholder'));
}

/** Checks populated databases are refused, even when unrelated collections contain the data. */
async function checkEmptyGuard() {
  const db = {
    listCollections: () => ({ toArray: async () => [{ name: 'unrelated' }] }),
    collection: () => ({ findOne: async () => ({ _id: 'existing' }) })
  };
  await assert.rejects(assertEmptyDatabase(db), SeedError);
  db.collection = () => ({ findOne: async () => null });
  await assert.doesNotReject(assertEmptyDatabase(db));
}

